// runStatisticsReport is shared by the 9 statistics.* discriminator methods.
// Centralizing the PUT /statistics?type=<X> shape here keeps each method file
// thin and consistent — the only variance across the 9 endpoints is the
// type query param and the user-facing labels.
func runStatisticsReport(cmd *cobra.Command, flags *rootFlags, typeParam, resource, start, end string, laundry int, timezone string) error {
	if start == "" {
		return fmt.Errorf("required flag \"%s\" not set", "start")
	}
	if end == "" {
		return fmt.Errorf("required flag \"%s\" not set", "end")
	}
	if laundry == 0 {
		return fmt.Errorf("required flag \"%s\" not set", "laundry")
	}

	c, err := flags.newClient()
	if err != nil {
		return err
	}

	path := "/statistics"
	params := map[string]string{"type": typeParam}
	body := map[string]any{
		"startDate": normalizeISODate(start, false),
		"endDate":   normalizeISODate(end, true),
		"laundry":   laundry,
		"timezone":  timezone,
	}
	data, statusCode, err := c.PutWithParams(path, params, body)
	if err != nil {
		return classifyAPIError(err, flags)
	}

	if flags.asJSON || (!isTerminal(cmd.OutOrStdout()) && !flags.csv && !flags.quiet && !flags.plain) {
		filtered := data
		if flags.selectFields != "" {
			filtered = filterFields(filtered, flags.selectFields)
		} else if flags.compact {
			filtered = compactFields(filtered)
		}
		envelope := map[string]any{
			"action":   "put",
			"resource": resource,
			"path":     path,
			"type":     typeParam,
			"status":   statusCode,
			"success":  statusCode >= 200 && statusCode < 300,
		}
		if flags.dryRun {
			envelope["dry_run"] = true
			envelope["status"] = 0
			envelope["success"] = false
		}
		if len(filtered) > 0 {
			var parsed any
			if err := json.Unmarshal(filtered, &parsed); err == nil {
				envelope["data"] = parsed
			}
		}
		envelopeJSON, err := json.Marshal(envelope)
		if err != nil {
			return err
		}
		return printOutput(cmd.OutOrStdout(), json.RawMessage(envelopeJSON), true)
	}
	return printOutputWithFlags(cmd.OutOrStdout(), data, flags)
}

// normalizeISODate accepts YYYY-MM-DD or full ISO8601 and returns an ISO8601
// string. For YYYY-MM-DD, expands to start-of-day or end-of-day depending on
// the endOfDay flag.
func normalizeISODate(s string, endOfDay bool) string {
	if len(s) == 10 { // YYYY-MM-DD shape
		if endOfDay {
			return s + "T23:59:59Z"
		}
		return s + "T00:00:00Z"
	}
	return s
}
